begin;
do $guard$ begin
 perform 1 from public.kpi_state where id for update;
 if (select revision from public.kpi_state where id)<>2 then raise exception 'Data changed: rebuild the import'; end if;
 if exists(select 1 from public.kpi_records where table_name='kpi_cong_viec') then raise exception 'Tasks already exist: review before import'; end if;
end $guard$;
insert into public.kpi_tables values ('kpi_thuong_chuyen_ky','["id","email","sourcePeriod","targetPeriod","examYear","assessmentYear","taskId","category","reference","requested","approved","status","version","at","reviewer","reviewNote"]'::jsonb) on conflict(table_name) do update set headers=excluded.headers;
update public.kpi_tables set headers=headers||'["mandatory","periodic"]'::jsonb where table_name='bang_luong_hoa_kpi' and not(headers ? 'mandatory');
insert into public.kpi_records(table_name,row_no,data) select 'bang_luong_hoa_kpi',ord+1,c||jsonb_build_object('_row',ord+1) from jsonb_array_elements($catalog$[{"id": "GVBM-1", "role": "GVBM", "title": "Ra vào lớp và tham gia họp đúng giờ, không bỏ tiết, không bỏ họp", "output": "Theo dõi BGH và Điểm danh sổ họp", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Dữ liệu BGH và Sổ điểm danh", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-2", "role": "GVBM", "title": "Xây dựng kế hoạch bài dạy, học liệu và chuẩn bị phương tiện, thiết bị dạy học theo yêu cầu của chương trình và kế hoạch giáo dục nhà trường.", "output": "Kế hoạch bài dạy, học liệu", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Kế hoạch bài dạy", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": true}, {"id": "GVBM-3", "role": "GVBM", "title": "Tổ chức dạy học đúng chương trình, yêu cầu cần đạt, đúng thời gian và bảo đảm chất lượng các tiết dạy theo thời khóa biểu, phân công chuyên môn và định mức tiết dạy theo quy định.", "output": "Lịch giảng dạy / Sổ đầu bài", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Sổ đầu bài, TKB", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-4", "role": "GVBM", "title": "Tổ chức kiểm tra, đánh giá thường xuyên, định kỳ và cập nhật điểm số, nhận xét học sinh", "output": "Bảng điểm môn học và học bạ điện tử", "sourceDue": "Theo lịch", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Dữ liệu điểm số đồng bộ trên VnEdu", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": true}, {"id": "GVBM-5", "role": "GVBM", "title": "Xây dựng đề, đáp án, hướng dẫn chấm và thực hiện kiểm tra, đánh giá kết quả học tập, sự tiến bộ của học sinh theo phân công và quy định.", "output": "Đề kiểm tra, đáp án, ma trận", "sourceDue": "2026-09-30T00:00:00", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Hồ sơ đề thi, đáp án", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-6", "role": "GVBM", "title": "Phân tích kết quả học tập và sự tiến bộ của học sinh theo từng giai đoạn; xác định những nội dung cần điều chỉnh và đề xuất biện pháp nâng cao chất lượng dạy học.", "output": "Báo cáo phân tích chất lượng", "sourceDue": "2026-09-30T00:00:00", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Báo cáo chuyên môn", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-7", "role": "GVBM", "title": "Thực hiện phụ đạo, hỗ trợ học sinh chưa đạt yêu cầu theo kế hoạch; bồi dưỡng học sinh giỏi, hướng dẫn nghiên cứu khoa học hoặc tham gia các kỳ thi khi được phân công.", "output": "Kế hoạch & Danh sách HS", "sourceDue": "2026-09-30T00:00:00", "kind": "Thường xuyên", "base": 10.0, "coef": 1.2, "max": 12.0, "evidence": "Hồ sơ phụ đạo, bồi dưỡng HSG", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-8", "role": "GVBM", "title": "Thực hiện giáo dục hòa nhập đối với học sinh thuộc phạm vi được giao; phối hợp thực hiện các biện pháp hỗ trợ phù hợp với từng đối tượng học sinh.", "output": "Kế hoạch giáo dục cá nhân hóa", "sourceDue": "2026-09-30T00:00:00", "kind": "Thường xuyên", "base": 10.0, "coef": 1.2, "max": 12.0, "evidence": "Hồ sơ theo dõi HS hòa nhập", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-9", "role": "GVBM", "title": "Tham gia đầy đủ sinh hoạt tổ, nhóm chuyên môn, nghiên cứu bài học, chuyên đề, dự giờ, thao giảng và các hoạt động phát triển chuyên môn theo kế hoạch.", "output": "Biên bản sinh hoạt tổ/nhóm", "sourceDue": "Hằng tháng", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Biên bản họp tổ chuyên môn", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-10", "role": "GVBM", "title": "Tham gia đào tạo, bồi dưỡng, tự bồi dưỡng chuyên môn, nghiệp vụ và thực hiện các yêu cầu về phát triển năng lực nghề nghiệp giáo viên.", "output": "Chứng nhận / Báo cáo", "sourceDue": "2026-09-30T00:00:00", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Chứng chỉ, giấy chứng nhận", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-11", "role": "GVBM", "title": "Ứng dụng công nghệ thông tin, chuyển đổi số, học liệu số, thiết bị và các phương tiện dạy học phù hợp trong quá trình giảng dạy.", "output": "Bài giảng điện tử / Học liệu số", "sourceDue": "Hằng tháng", "kind": "Thường xuyên", "base": 10.0, "coef": 1.2, "max": 12.0, "evidence": "Kho học liệu số, LMS", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-12", "role": "GVBM", "title": "Chủ động đổi mới phương pháp, hình thức tổ chức dạy học, kiểm tra đánh giá và khai thác hiệu quả các nguồn học liệu phục vụ dạy học.", "output": "Sản phẩm đổi mới PPDH", "sourceDue": "2026-09-30T00:00:00", "kind": "Thường xuyên", "base": 10.0, "coef": 1.2, "max": 12.0, "evidence": "Báo cáo chuyên đề, sáng kiến", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": true, "periodic": false}, {"id": "GVBM-13", "role": "GVBM", "title": "Tham gia các hoạt động giáo dục, hoặc các nhiệm vụ khác khi được Hiệu trưởng, Phó Hiệu trưởng  phân công.", "output": "Báo cáo kết quả / Kế hoạch", "sourceDue": "", "kind": "Đột xuất", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Minh chứng phân công", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": false, "periodic": false}, {"id": "GVBM-14", "role": "GVBM", "title": "Tham gia các hoạt động giáo dục, hoặc các nhiệm vụ chuyên môn khác khi được Sở Giáo dục phân công.", "output": "Biên bản kiểm tra / Báo cáo", "sourceDue": "", "kind": "Đột xuất", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "QĐ/Hồ sơ thực hiện nhiệm vụ", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVBM", "mandatory": false, "periodic": false}, {"id": "GVCN-1", "role": "GVCN", "title": "Xây dựng và thực hiện kế hoạch công tác chủ nhiệm, kế hoạch giáo dục của lớp phù hợp với kế hoạch giáo dục nhà trường.", "output": "Kế hoạch công tác chủ nhiệm", "sourceDue": "2026-08-30T00:00:00", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Văn bản ban hành và hồ sơ trình", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVCN", "mandatory": true, "periodic": false}, {"id": "GVCN-2", "role": "GVCN", "title": "Nắm bắt, cập nhật và quản lý đầy đủ, chính xác thông tin về học sinh thuộc lớp chủ nhiệm; kịp thời phát hiện những vấn đề cần quan tâm, hỗ trợ.", "output": "Hồ sơ thông tin học sinh", "sourceDue": "2026-08-30T00:00:00", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Sổ chủ nhiệm / CSDL học sinh", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVCN", "mandatory": true, "periodic": false}, {"id": "GVCN-3", "role": "GVCN", "title": "Theo dõi thường xuyên tình hình chuyên cần, học tập, rèn luyện, ý thức chấp hành nội quy và sự tiến bộ của từng học sinh.", "output": "Sổ theo dõi chuyên cần", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Sổ đầu bài / Sổ điểm danh", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVCN", "mandatory": true, "periodic": false}, {"id": "GVCN-4", "role": "GVCN", "title": "Tổ chức tiết sinh hoạt lớp và các hoạt động giáo dục tập thể theo kế hoạch; xây dựng tập thể lớp đoàn kết, tích cực, tự quản và có ý thức trách nhiệm.", "output": "Biên bản sinh hoạt lớp", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Giáo án HĐTN-HN / Sổ chủ nhiệm", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVCN", "mandatory": true, "periodic": false}, {"id": "GVCN-5", "role": "GVCN", "title": "Hướng dẫn ban cán sự lớp tổ chức, điều hành và quản lý các hoạt động của lớp; phát huy vai trò tự quản của học sinh.", "output": "Sổ tay cán sự lớp", "sourceDue": "Hằng tháng", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Sổ phân công nhiệm vụ lớp", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVCN", "mandatory": true, "periodic": false}, {"id": "GVCN-6", "role": "GVCN", "title": "Tư vấn, hỗ trợ ban đầu đối với học sinh gặp khó khăn trong học tập, tâm lý, quan hệ xã hội; phối hợp với nhà trường, cha mẹ học sinh và các lực lượng có liên quan khi cần thiết.", "output": "Nhật ký tư vấn tâm lý", "sourceDue": "Hằng tháng", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Biên bản tư vấn / Sổ theo dõi", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVCN", "mandatory": true, "periodic": false}, {"id": "GVCN-7", "role": "GVCN", "title": "Chủ động thực hiện các biện pháp hỗ trợ đối với học sinh có nguy cơ bỏ học, vi phạm nội quy, sa sút trong học tập hoặc rèn luyện; theo dõi kết quả và báo cáo nhà trường theo quy định.", "output": "Hồ sơ hỗ trợ HS cá biệt", "sourceDue": "2026-09-30T00:00:00", "kind": "Thường xuyên", "base": 10.0, "coef": 1.2, "max": 12.0, "evidence": "Biên bản làm việc với PHHS, BGH", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVCN", "mandatory": true, "periodic": false}, {"id": "GVCN-8", "role": "GVCN", "title": "Phối hợp với giáo viên bộ môn trong theo dõi, quản lý, giáo dục và hỗ trợ học sinh; trao đổi kịp thời những vấn đề phát sinh liên quan đến học sinh.", "output": "Biên bản phối hợp GVBM", "sourceDue": "Hằng tháng", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Sổ ghi chép / Sổ liên lạc", "source": "1. DANH_MUC_CONG_VIEC(1).xlsx / GVCN", "mandatory": true, "periodic": false}, {"id": "GVCN-9", "role": "GVCN", "title": "Phối hợp, trao đổ