 false}, {"id": "TVTL-2", "role": "TVTL", "title": "Thiết lập, quản lý và vận hành các kênh tiếp nhận thông tin, nhu cầu hỗ trợ, tư vấn của học sinh; bảo đảm thuận tiện, phù hợp và an toàn.", "output": "Kênh thông tin/Sổ tay", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Link kênh trực tuyến/Sổ tiếp nhận", "source": "To_van_phong.xlsx / TVTL", "mandatory": true, "periodic": false}, {"id": "TVTL-3", "role": "TVTL", "title": "Tổ chức tư vấn, hỗ trợ học sinh bằng hình thức trực tiếp hoặc trực tuyến phù hợp với nội dung, nhu cầu và điều kiện thực tế.", "output": "Biên bản tư vấn", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Sổ nhật ký tư vấn (bảo mật)", "source": "To_van_phong.xlsx / TVTL", "mandatory": true, "periodic": false}, {"id": "TVTL-4", "role": "TVTL", "title": "Tư vấn, hỗ trợ học sinh về học tập, tâm lý, quan hệ xã hội, kỹ năng ứng xử, kỹ năng sống và những vấn đề liên quan đến quá trình học tập, rèn luyện.", "output": "Hồ sơ ca tư vấn", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Phiếu ghi nhận/Hồ sơ ca", "source": "To_van_phong.xlsx / TVTL", "mandatory": true, "periodic": false}, {"id": "TVTL-5", "role": "TVTL", "title": "Tư vấn, hỗ trợ hoặc tổ chức truyền thông, giáo dục phù hợp về giới, sức khỏe sinh sản, hướng nghiệp, lựa chọn nghề nghiệp, việc làm và khởi nghiệp theo chương trình, kế hoạch của nhà trường.", "output": "Tài liệu truyền thông", "sourceDue": "Hằng tháng", "kind": "Thường xuyên", "base": 10.0, "coef": 1.2, "max": 12.0, "evidence": "Hồ sơ chuyên đề/Hình ảnh sự kiện", "source": "To_van_phong.xlsx / TVTL", "mandatory": true, "periodic": false}, {"id": "TVTL-6", "role": "TVTL", "title": "Chủ động rà soát, tiếp nhận thông tin và phát hiện sớm học sinh có nguy cơ gặp khó khăn về tâm lý, học tập, quan hệ xã hội hoặc hoàn cảnh gia đình để kịp thời hỗ trợ.", "output": "Báo cáo r