an_phong.xlsx / TVTL", "mandatory": true, "periodic": false}, {"id": "TVTL-11", "role": "TVTL", "title": "Theo dõi kết quả hỗ trợ, tiếp nhận phản hồi và thực hiện hỗ trợ tiếp nối đối với học sinh khi cần thiết; báo cáo những trường hợp cần sự chỉ đạo, phối hợp của nhà trường.", "output": "Phiếu theo dõi", "sourceDue": "Hằng tháng", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Nhật ký đánh giá sự tiến bộ", "source": "To_van_phong.xlsx / TVTL", "mandatory": true, "periodic": false}, {"id": "TVTL-12", "role": "TVTL", "title": "Thực hiện thống kê, tổng hợp, lưu trữ minh chứng và báo cáo định kỳ, đột xuất về công tác tư vấn học sinh, tư vấn học đường và công tác xã hội theo yêu cầu của Hiệu trưởng.", "output": "Báo cáo tổng hợp", "sourceDue": "30/9/2026", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Báo cáo lưu trữ nộp BGH", "source": "To_van_phong.xlsx / TVTL", "mandatory": true, "periodic": false}, {"id": "GIAOVU-1", "role": "GIAOVU", "title": "Xây dựng và thực hiện kế hoạch công tác giáo vụ theo kế hoạch giáo dục và yêu cầu quản lý của nhà trường.", "output": "Kế hoạch công tác", "sourceDue": "30/8/2026", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Văn bản Kế hoạch được duyệt", "source": "To_van_phong.xlsx / GIÁO VỤ", "mandatory": true, "periodic": false}, {"id": "GIAOVU-2", "role": "GIAOVU", "title": "Quản lý, cập nhật và lưu trữ hồ sơ, sổ sách, dữ liệu liên quan đến học sinh theo quy định.", "output": "Hồ sơ học sinh", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Hệ thống sổ sách/Hồ sơ lưu trữ", "source": "To_van_phong.xlsx / GIÁO VỤ", "mandatory": true, "periodic": false}, {"id": "GIAOVU-3", "role": "GIAOVU", "title": "Phối hợp thực hiện công tác tuyển sinh, tiếp nhận học sinh, chuyển trường, chuyển lớp và các thủ tục liên quan theo phân công của Hiệu trưởng.", "output": "Hồ sơ thuyên chuyển", "sourceDue": "Khi p