periodic": false}, {"id": "GIAOVU-8", "role": "GIAOVU", "title": "Cung cấp, tổng hợp số liệu về học sinh phục vụ công tác quản lý, thống kê, báo cáo và các yêu cầu nghiệp vụ của nhà trường theo phân công.", "output": "Báo cáo số liệu", "sourceDue": "Khi có yêu cầu", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Biểu mẫu thống kê/File dữ liệu", "source": "To_van_phong.xlsx / GIÁO VỤ", "mandatory": true, "periodic": false}, {"id": "GIAOVU-9", "role": "GIAOVU", "title": "Quản lý, cập nhật và lưu trữ hồ sơ giáo vụ, dữ liệu học sinh trên các hệ thống quản lý được nhà trường sử dụng; bảo đảm an toàn và bảo mật thông tin theo quy định.", "output": "Dữ liệu hệ thống", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Lịch sử cập nhật CSDL/Enetviet/LMS", "source": "To_van_phong.xlsx / GIÁO VỤ", "mandatory": true, "periodic": false}, {"id": "GIAOVU-10", "role": "GIAOVU", "title": "Thực hiện thống kê, tổng hợp, lưu trữ minh chứng và báo cáo định kỳ, đột xuất về công tác giáo vụ theo yêu cầu của Hiệu trưởng.", "output": "Văn bản báo cáo", "sourceDue": "30/9/2026", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Văn bản báo cáo nộp BGH", "source": "To_van_phong.xlsx / GIÁO VỤ", "mandatory": true, "periodic": false}, {"id": "GIAOVU-11", "role": "GIAOVU", "title": "Thực hiện hồ sơ nâng lương thường xuyên, nâng lương trước thời hạn", "output": "Văn bản báo cáo", "sourceDue": "Hằng tháng", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Văn bản báo cáo nộp BGH", "source": "To_van_phong.xlsx / GIÁO VỤ", "mandatory": true, "periodic": false}, {"id": "QS-1", "role": "QS", "title": "Theo dõi tình hình chuyên cần, việc ra vào trường và sự có mặt của học sinh theo thời gian, khu vực và nhiệm vụ được phân công.", "output": "Sổ trực ban", "sourceDue": "Hằng ngày", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Sổ trực ban