ax": 11.0, "evidence": "Tin nhắn/Sổ liên lạc", "source": "To_van_phong.xlsx / QS", "mandatory": true, "periodic": false}, {"id": "QS-7", "role": "QS", "title": "Phối hợp với giáo viên chủ nhiệm, giáo vụ, cha mẹ học sinh và các bộ phận có liên quan trong việc xác minh thông tin, làm rõ vụ việc và hỗ trợ học sinh theo chỉ đạo của nhà trường.", "output": "Biên bản làm việc", "sourceDue": "Khi phát sinh", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Biên bản làm việc với PHHS/GVCN", "source": "To_van_phong.xlsx / QS", "mandatory": true, "periodic": false}, {"id": "QS-8", "role": "QS", "title": "Thực hiện các biện pháp hỗ trợ, ổn định tình hình ban đầu đối với các vụ việc liên quan đến trật tự, an toàn học sinh; kịp thời báo cáo giáo viên chủ nhiệm hoặc Ban Giám hiệu khi vụ việc vượt quá phạm vi nhiệm vụ.", "output": "Báo cáo nhanh", "sourceDue": "Khi phát sinh", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Biên bản xử lý sự cố ban đầu", "source": "To_van_phong.xlsx / QS", "mandatory": true, "periodic": false}, {"id": "QS-9", "role": "QS", "title": "Theo dõi, ghi nhận việc thực hiện các yêu cầu, biện pháp giáo dục học sinh sau khi có ý kiến chỉ đạo của giáo viên chủ nhiệm hoặc Ban Giám hiệu; báo cáo kết quả thực hiện.", "output": "Phiếu theo dõi", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.1, "max": 11.0, "evidence": "Nhật ký theo dõi HS vi phạm", "source": "To_van_phong.xlsx / QS", "mandatory": true, "periodic": false}, {"id": "QS-10", "role": "QS", "title": "Tổng hợp tình hình chuyên cần, nền nếp, vi phạm nội quy và các vụ việc liên quan đến học sinh theo ngày, tuần hoặc thời gian được yêu cầu.", "output": "Bảng tổng hợp", "sourceDue": "Hằng tuần", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Báo cáo thi đua tuần/tháng", "source": "To_van_phong.xlsx / QS", "mandatory": true, "periodic": false}, {"id": "QS-11", "role": "QS", "title": "Báo cáo kị