ef": 1.1, "max": 11.0, "evidence": "Báo cáo sơ kết/tổng kết CĐS", "source": "To_van_phong.xlsx / CNTT", "mandatory": true, "periodic": false}, {"id": "CNTT-14", "role": "CNTT", "title": "Quản lý, cập nhật hồ sơ, dữ liệu, minh chứng và thực hiện chế độ thống kê, báo cáo về công nghệ thông tin, chuyển đổi số theo định kỳ hoặc đột xuất; thực hiện các nhiệm vụ khác về CNTT, chuyển đổi số theo phân công của Hiệu trưởng.", "output": "Hồ sơ minh chứng CNTT", "sourceDue": "30/9/2026", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Thư mục lưu trữ minh chứng CĐS", "source": "To_van_phong.xlsx / CNTT", "mandatory": true, "periodic": false}, {"id": "BV-1", "role": "BV", "title": "Thực hiện trực bảo vệ, trực cổng và bàn giao ca theo lịch phân công; bảo đảm duy trì lực lượng trực trong thời gian được giao.", "output": "Sổ trực ca / Bàn giao", "sourceDue": "Hằng ngày", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Sổ trực bảo vệ / Sổ giao ca", "source": "To_van_phong.xlsx / BV", "mandatory": true, "periodic": false}, {"id": "BV-2", "role": "BV", "title": "Kiểm soát người, phương tiện ra vào trường theo nội quy, quy định của nhà trường; ghi nhận các trường hợp cần thiết và kịp thời báo cáo người có thẩm quyền khi có dấu hiệu bất thường.", "output": "Sổ kiểm soát ra vào", "sourceDue": "Hằng ngày", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Sổ ghi nhận phương tiện/khách", "source": "To_van_phong.xlsx / BV", "mandatory": true, "periodic": false}, {"id": "BV-3", "role": "BV", "title": "Tiếp nhận, hướng dẫn và hỗ trợ khách đến liên hệ công tác; phối hợp với văn phòng hoặc bộ phận có liên quan để thực hiện quy trình tiếp khách theo quy định của nhà trường.", "output": "Sổ tiếp khách", "sourceDue": "Hằng ngày", "kind": "Thường xuyên", "base": 10.0, "coef": 1.0, "max": 10.0, "evidence": "Sổ ghi chép tiếp khách", "source": "To_van_phong.xlsx / BV", "mandatory": true, "periodic": false}, {"id": "B