 select data->>'value' into period from public.kpi_records where table_name='kpi_cau_hinh' and data->>'key'='period';
 for person in select data from public.kpi_records where table_name='gvcnv' order by row_no loop
 person_email=lower(trim(person.data->>'Email'));job=lower(trim(coalesce(person.data->>'Chức vụ','')));
 if coalesce(person.data->>'Vai trò KPI','')<>'' then roles=regexp_split_to_array(upper(trim(person.data->>'Vai trò KPI')),'[;,|\s]+');
 elsif job like '%phó hiệu trưởng%' then roles=array['PHT'];
 elsif job like '%hiệu trưởng%' then roles=array['HT'];
 elsif job like '%tổ trưởng%' or job='ttcm' then roles=array['GVBM','TTCM'];
 elsif job like '%tổ phó%' or job='tpcm' then roles=array['GVBM','TPCM'];
 elsif job like '%tổ viên%' or job like '%giáo viên%' or job like '%gvbm%' then roles=array['GVBM'];
 else roles=array[]::text[];end if;
 if coalesce(person.data->>'Lớp chủ nhiệm','')<>'' or job like '%gvcn%' then roles=array_append(roles,'GVCN');end if;
 if lower(coalesce(person.data->>'Hòa nhập','')) in ('có','true','1','x') or job like '%hòa nhập%' then roles=array_append(roles,'HOANHAP');end if;
 if coalesce(person.data->>'Vai trò KPI','')='' and lower(coalesce(nullif(person.data->>'Tổ',''),person.data->>'Môn','')) like '%văn phòng%' then
 roles=array_remove(array_remove(array_remove(roles,'GVBM'),'TTCM'),'TPCM');
 if job like '%tổ trưởng%' then roles=array_append(roles,'TTVP');end if;
 if job like '%tổ phó%' then roles=array_append(roles,'TPVP');end if;
 if job like '%kế toán%' then roles=array_append(roles,'KT');end if;
 if job like '%thủ quỹ%' then roles=array_append(roles,'TQUY');end if;
 if job like '%văn thư%' then roles=array_append(roles,'VT');end if;
 if job like '%y tế%' then roles=array_append(roles,'YTE');end if;
 if job like '%bảo vệ%' then roles=array_append(roles,'BV');end if;
 if job like '%phục vụ%' then roles=array_append(roles,'PV');end if;
 if job like '%thư viện%' then roles=array_append(roles,'TVIEN');end if;
 if job like '%thiết bị%' then roles=array_append(roles,'TBTN');end if;
 if job like '%giáo vụ%' then roles=array_append(roles,'GIAOVU');end if;
 if job like '%công nghệ thông tin%' then roles=array_append(roles,'CNTT');end if;
 end if;
required='[]'::jsonb;
 for criterion in select data from public.kpi_records where table_name='bang_luong_hoa_kpi' and data->>'role'=any(roles) and (data->>'mandatory')::boolean order by row_no loop
 required=required||jsonb_build_array(criterion.data->>'id');
 select coalesce(max(row_no),1)+1 into n from public.kpi_records where table_name='kpi_cong_viec';uid=gen_random_uuid()::text;
 insert into public.kpi_records values ('kpi_cong_viec',n,jsonb_build_object('_row',n,'id',uid,'email',person_email,'period',period,'criterionId',criterion.data->>'id','title',criterion.data->>'title','role',criterion.data->>'role','output',criterion.data->>'output','due','','kind',criterion.data->>'kind','base',(criterion.data->>'base')::numeric,'coef',(criterion.data->>'coef')::numeric,'inPlan',true,'planStatus','approved','planAt',now(),'progress',0,'quality',0,'completed',false,'reviewStatus','draft','version',1,'cancelled',false,'note','Nhiệm vụ bắt buộc theo vai trò; người quản lý ấn định hạn.'));
 end loop;
 if jsonb_array_length(required)>0 then
 select coalesce(max(row_no),1)+1 into n from public.kpi_records where table_name='kpi_ke_hoach';
 insert into public.kpi_records values ('kpi_ke_hoach',n,jsonb_build_object('_row',n,'id',gen_random_uuid()::text,'email',person_email,'period',period,'requiredIds',required::text,'status','confirmed','note','Kế hoạch bắt buộc tự ghi nhận theo danh mục và vai trò. Hạn do quản lý ấn định.','reviewer','SYSTEM-MANDATORY','version',1));end if;
 end loop;
end $seed$;
insert into public.kpi_records select 'kpi_cau_hinh',coalesce(max(row_no),1)+1,jsonb_build_object('_row',coalesce(max(row_no),1)+1,'key','schoolQuarters','value','[["2026-09-05","2026-11-06"],["2026-11-07","2027-01-09"],["2027-01-10","2027-03-12"],["2027-03-13","2027-05-29"]]') from public.kpi_records where table_name='kpi_cau_hinh';
insert into public.kpi_records select 'kpi_nhat_ky',coalesce(max(row_no),1)+1,jsonb_build_object('_row',coalesce(max(row_no),1)+1,'at',now(),'actor','SYSTEM-SOURCE-UPDATE','action','CATALOG_3_2','entity','2026-2027','before','59 source criteria; no operational tasks','after','233 source criteria; mandatory tasks per assigned role; dates unset') from public.kpi_records where table_name='kpi_nhat_ky';
update public.kpi_state set revision=revision+1 where id;
commit;
select table_name,count(*) as rows from public.kpi_records group by table_name order by table_name;
